// Offline helper for compiling WarcraftXL's shader-model-3 HLSL with Wine's
// D3DCompiler. The generated bytes are ordinary D3D9 shader bytecode.
#include <windows.h>
#include <d3dcompiler.h>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>

int main(int argc, char** argv) {
    if (argc < 4) {
        std::fprintf(stderr, "usage: wxl_compile_shader <source> <profile> <output> [NAME=VALUE ...]\n");
        return 2;
    }
    const int chars = MultiByteToWideChar(CP_UTF8, MB_ERR_INVALID_CHARS, argv[1], -1, nullptr, 0);
    if (!chars) return 2;
    std::vector<wchar_t> source(chars);
    if (!MultiByteToWideChar(CP_UTF8, MB_ERR_INVALID_CHARS, argv[1], -1, source.data(), chars)) return 2;
    ID3DBlob* bytecode = nullptr;
    ID3DBlob* errors = nullptr;
    std::vector<D3D_SHADER_MACRO> macros;
    macros.reserve(static_cast<size_t>(argc - 3));
    for (int i = 4; i < argc; ++i) {
        char* equals = std::strchr(argv[i], '=');
        if (!equals || equals == argv[i] || !equals[1]) return 2;
        *equals = '\0';
        macros.push_back({argv[i], equals + 1});
    }
    macros.push_back({nullptr, nullptr});
    const HRESULT result = D3DCompileFromFile(source.data(), macros.data(), D3D_COMPILE_STANDARD_FILE_INCLUDE,
                                             "main", argv[2], D3DCOMPILE_OPTIMIZATION_LEVEL3, 0,
                                             &bytecode, &errors);
    if (errors) {
        std::fwrite(errors->GetBufferPointer(), 1, errors->GetBufferSize(), stderr);
        errors->Release();
    }
    if (FAILED(result) || !bytecode) return 1;
    FILE* output = std::fopen(argv[3], "wb");
    if (!output) { bytecode->Release(); return 1; }
    const size_t size = bytecode->GetBufferSize();
    const bool ok = std::fwrite(bytecode->GetBufferPointer(), 1, size, output) == size;
    const bool closed = std::fclose(output) == 0;
    bytecode->Release();
    return ok && closed ? 0 : 1;
}
